import six
import struct
import tempfile

from ute_admin_infomodel.listener import InfoModelChangeListener

from .frame import FRAME_PREFIX, FrameType, CompressionType, ChangeType


def write_changeset(function):
    """Write InfoModel changeset generated by wrapped function."""

    def _wrap(recorder, changes, timestamp):
        recorder._initialize_if_first_update()
        changeset = function(recorder, changes, timestamp)
        recorder._write_changeset(changeset, timestamp)
    return _wrap


class Ims2Recorder(InfoModelChangeListener):

    def __init__(self):
        self.tempfile = tempfile.TemporaryFile()
        self.definitions = None
        self.initialized = False

    def save(self, output_path):
        """Save recorded IMS2 log file."""
        self.tempfile.seek(0)
        with open(output_path, 'wb') as ims2:
            ims2.write(self.tempfile.read())

    def close(self):
        """Close temporary file."""
        self.tempfile.close()

    def on_definitions_change(self, definitions):
        """Callend when managed objects definitions are changed."""
        self._initialize_if_first_update()
        self.definitions = definitions
        self._write_meta(definitions.get_meta())

    def on_reset(self, timestamp):
        """Called when connection reset."""
        self._initialize_if_first_update()
        self._wite_reset(timestamp)

    @write_changeset
    def on_remove(self, removed, timestamp):
        """Called when infomodel object is removed."""
        return [self._prepare_removing_change(dist_name) for dist_name in removed]

    @write_changeset
    def on_update(self, changed, timestamp):
        """Called when infomodel object changes."""
        return [self._prepare_updating_change(dist_name, object_dump) for dist_name, object_dump in six.iteritems(changed)]

    @write_changeset
    def on_oper_exec(self, operation, timestamp):
        """Called when infomodel operation is executed."""
        return [self._prepare_operation_request(*operation)]

    @write_changeset
    def on_oper_stat(self, status, timestamp):
        """Called when infomodel operation is executed."""
        return [self._prepare_operation_status(*status)]

    def on_wrong_parameter(self, dist_name, parameter, value, error_msg):
        """Called when wrong parameter value is set"""
        pass

    def on_missing_mo_definition(self, dist_name):
        """Called when managed object definition is missing"""
        pass

    def _prepare_removing_change(self, dist_name):
        dist_name = self._string_to_bytes(dist_name)
        fmt = '>H{}sc'.format(len(dist_name))
        return struct.pack(fmt, len(dist_name), dist_name, six.int2byte(ChangeType.REMOVING))

    def _prepare_updating_change(self, dist_name, object_dump):
        encoder = self.definitions.get_encoder(dist_name)
        dist_name = self._string_to_bytes(dist_name)
        protobuf_msg = encoder.encode(object_dump)
        fmt = '>H{}sci{}s'.format(len(dist_name), len(protobuf_msg))
        return struct.pack(fmt, len(dist_name), dist_name, six.int2byte(ChangeType.UPDATING), len(protobuf_msg), protobuf_msg)

    def _prepare_operation_request(self, sender_sic_address, request_id, dist_name, object_dump):
        encoder = self.definitions.get_encoder(dist_name)
        dist_name = self._string_to_bytes(dist_name)
        protobuf_msg = encoder.encode(object_dump)
        fmt = '>H{}sciHii{}s'.format(len(dist_name), len(protobuf_msg))
        return struct.pack(fmt, len(dist_name), dist_name, six.int2byte(ChangeType.EXECUTION_REQUESTING),
                           sender_sic_address, 0, request_id, len(protobuf_msg), protobuf_msg)

    def _prepare_operation_status(self, sender_sic_address, request_id, dist_name, status):
        dist_name = self._string_to_bytes(dist_name)
        fmt = '>H{}sciHii'.format(len(dist_name))
        return struct.pack(fmt, len(dist_name), dist_name, six.int2byte(ChangeType.EXECUTION_STATUS), sender_sic_address, 0, request_id, status)

    def _write_changeset(self, changeset, timestamp):
        number_of_changes = len(changeset)
        changeset = six.b('').join(changeset)
        changeset_format = '>qi{}s'.format(len(changeset))
        self._write_frame(FrameType.CHANGESET, struct.pack(changeset_format, timestamp, number_of_changes, changeset))

    def _wite_reset(self, timestamp):
        self._write_frame(FrameType.RESET, struct.pack('>q', timestamp))

    def _write_meta(self, meta):
        self._write_frame(FrameType.META, meta)

    def _write_frame(self, frame_type, payload, compression_type=CompressionType.NONE):
        self._write_bytes(FRAME_PREFIX)
        self._write_int(frame_type)
        self._write_int(compression_type)
        self._write_int(len(payload))
        self._write_bytes(payload)

    def _initialize_if_first_update(self):
        if not self.initialized:
            self._write_header(version=1, additional_info='CommandLineRecorder')
            self.initialized = True

    def _write_header(self, version, additional_info):
        self._write_int(version)
        self._write_int(len(additional_info) + 4)
        self._write_int(len(additional_info))
        self._write_string(additional_info)

    def _write_int(self, value):
        self.tempfile.write(struct.pack('>i', value))

    def _write_string(self, string):
        self._write_bytes(self._string_to_bytes(string))

    def _write_bytes(self, bytes):
        self.tempfile.write(bytes)

    def _string_to_bytes(self, string):
        if six.PY3 and isinstance(string, str):
            return string.encode('utf-8')
        return string
